; Wiegand 26-bit reader frame on DATA0 / DATA1; one 26-bit frame (parity included) per host word, acknowledged
; Generated by escgen from protocols/wiegand_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: SIA AC-01-1996.10, Access Control Standard Protocol for the 26-Bit Wiegand Reader Interface (limits as quoted by vendors, e.g. Suprema support article 24000028006: pulse width 20 to 100 us, pulse interval 200 us to 20 ms)
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ W, CLK_KHZ * 50 // 1000
.equ I, CLK_KHZ
.equ GAP, CLK_KHZ * 25
.default PIN_D0, 0
.equ P_D0, 1 << PIN_D0
.default PIN_D1, 1
.equ P_D1, 1 << PIN_D1

.own  PIN_D0, CTX
.own  PIN_D1, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_D0 | P_D1, P_D0 | P_D1, P_D0 | P_D1 ; idle levels
    ADDT  1
packet:
    POP   r1                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    MOV   r0, r1                      ; 26 bits, MSB first, each zero or one
    SHL   r0, 6                       ; the field's first bit to bit 31
    MOVI  r3, 0
bit1:
    SHL   r0, 1                       ; C = the next bit
    JC    one2
    EMIT  P_D0, 0, P_D0               ; zero
    ADDT  W
    EMIT  P_D0, P_D0, P_D0
    ADDT  I - W
    JMP   next3
one2:
    EMIT  P_D1, 0, P_D1               ; one
    ADDT  W
    EMIT  P_D1, P_D1, P_D1
    ADDT  I - W
next3:
    ADDI  r3, 1
    CMPI  r3, 26                      ; Z after the last bit
    JNZ   bit1
    EMIT  P_D0, P_D0, P_D0            ; gap
    ADDT  GAP
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet
